def _fake_connection(monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.setenv("SUPABASE_URL", "http://127.0.0.1:54321")
    monkeypatch.setenv("SUPABASE_SERVICE_ROLE_KEY", "synthetic" * 3)

    def repository(_: IngestionConfig) -> MemoryRepository:
        return MemoryRepository()

    monkeypatch.setattr(cli, "SupabaseDocumentRepository", repository)


def test_default_inbox_is_used_by_cli(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    monkeypatch.chdir(tmp_path)
    inbox = tmp_path / "imports/private/permit-certificates/inbox"
    inbox.mkdir(parents=True)
    _fake_connection(monkeypatch)
    assert cli.main(["ingest"]) == 0
    assert capsys.readouterr().out == "created=0 skipped=0 failed=0\n"


def test_independent_document_failure_keeps_zero_exit(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    _ = write_corrupt_pdf(tmp_path)
    _fake_connection(monkeypatch)
    assert cli.main(["ingest", "--inbox", str(tmp_path)]) == 0
    output = capsys.readouterr().out
    assert output.startswith("created=0 skipped=0 failed=1\n")
    assert "corrupt_document" in output
    assert 'file="a.pdf" retryable=false' in output
    assert "synthetic" not in output


def test_missing_configuration_is_safe_nonzero(
    monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    monkeypatch.delenv("SUPABASE_URL", raising=False)
    monkeypatch.delenv("SUPABASE_SERVICE_ROLE_KEY", raising=False)
    assert cli.main(["ingest"]) == 1
    assert (
        capsys.readouterr().out
        == "system_failure stage=configuration code=invalid_supabase_settings\n"
    )


def test_filename_cannot_echo_local_credential(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch, capsys: pytest.CaptureFixture[str]
) -> None:
    _ = write_corrupt_pdf(tmp_path, "synthetic" * 3 + ".pdf")
    _fake_connection(monkeypatch)
    assert cli.main(["ingest", "--inbox", str(tmp_path)]) == 0
