create policy permit_documents_read on permit_documents for select to authenticated
using (
  (site_id_candidate is null and has_role(array['she_staff']::app_role[]))
  or (site_id_candidate is not null and can_read_site(site_id_candidate))
);

create trigger trg_audit_permit_documents
after insert or update or delete on permit_documents
for each row execute function audit_trigger();

create or replace function confirm_permit_document(
  p_document uuid,
  p_reviewed jsonb
) returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_document permit_documents%rowtype;
  v_keys text[];
  v_site_id uuid;
  v_permit_type permit_type;
  v_applicable boolean;
  v_grade text;
  v_detail text;
  v_items text[];
  v_quantity int;
  v_permit_no text;
  v_authority text;
  v_issued_on date;
  v_conditions text;
  v_status permit_status;
  v_evidence_path text;
  v_path_permit_id uuid;
  v_existing site_permits%rowtype;
  v_permit_id uuid;
  v_attachment attachments%rowtype;
begin
  if v_actor is null or not exists (
    select 1
    from profiles profile
    join role_assignments assignment on assignment.user_id = profile.id
    where profile.id = v_actor
      and profile.active
      and assignment.role = 'she_staff'
      and assignment.scope = 'company'
  ) then
    raise exception '활성 SHE팀 담당자만 인허가 문서를 확정할 수 있습니다.' using errcode = '42501';
  end if;

  select * into v_document
  from permit_documents
  where id = p_document
  for update;

  if not found then
    raise exception '검토할 인허가 문서를 찾을 수 없습니다.';
  end if;
  if v_document.status <> 'pending_review' then
    raise exception '대기 중인 인허가 문서만 확정할 수 있습니다.';
  end if;
  if jsonb_typeof(p_reviewed) is distinct from 'object' then
    raise exception '확정 값은 JSON 객체여야 합니다.';
  end if;

  select array_agg(key order by key) into v_keys from jsonb_object_keys(p_reviewed) key;
  if v_keys is distinct from array[
    'applicable', 'authority', 'conditions', 'detail', 'evidence_storage_path',
    'grade', 'issued_on', 'items', 'permit_no', 'permit_type', 'quantity',
    'site_id', 'status'
  ]::text[] then
    raise exception '확정 값의 필드가 계약과 일치하지 않습니다.';
  end if;

  if jsonb_typeof(p_reviewed -> 'site_id') is distinct from 'string'
     or (p_reviewed ->> 'site_id') !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'site_id는 유효한 UUID여야 합니다.';
  end if;
  v_site_id := (p_reviewed ->> 'site_id')::uuid;
  if not exists (select 1 from sites where id = v_site_id) then
    raise exception '확정 대상 사업장을 찾을 수 없습니다.';
  end if;
  if v_document.site_id_candidate is not null
     and v_document.site_id_candidate <> v_site_id then
    raise exception '확정 사업장이 문서 후보와 충돌합니다.';
  end if;

  if jsonb_typeof(p_reviewed -> 'permit_type') is distinct from 'string'
     or (p_reviewed ->> 'permit_type') not in (
       select unnest(enum_range(null::permit_type))::text
     ) then
    raise exception 'permit_type이 유효하지 않습니다.';
  end if;
  v_permit_type := (p_reviewed ->> 'permit_type')::permit_type;
  if v_document.permit_type_candidate is not null
     and v_document.permit_type_candidate <> v_permit_type then
    raise exception '확정 인허가 유형이 문서 후보와 충돌합니다.';
  end if;

  if jsonb_typeof(p_reviewed -> 'applicable') is distinct from 'boolean' then
    raise exception 'applicable은 boolean이어야 합니다.';
  end if;
  v_applicable := (p_reviewed ->> 'applicable')::boolean;

  if coalesce(jsonb_typeof(p_reviewed -> 'grade'), 'null') not in ('null', 'string')
     or coalesce(jsonb_typeof(p_reviewed -> 'detail'), 'null') not in ('null', 'string')
     or coalesce(jsonb_typeof(p_reviewed -> 'permit_no'), 'null') not in ('null', 'string')
     or coalesce(jsonb_typeof(p_reviewed -> 'authority'), 'null') not in ('null', 'string')
     or coalesce(jsonb_typeof(p_reviewed -> 'conditions'), 'null') not in ('null', 'string') then
    raise exception '선택 문자열 필드의 형식이 유효하지 않습니다.';
  end if;
  if exists (
    select 1
    from jsonb_each(p_reviewed) entry
    where entry.key in ('grade', 'detail', 'permit_no', 'authority', 'conditions')
      and jsonb_typeof(entry.value) = 'string'
      and btrim(entry.value #>> '{}') = ''
  ) then
    raise exception '선택 문자열 필드에 공백 값은 허용되지 않습니다.';
  end if;
  v_grade := p_reviewed ->> 'grade';
  v_detail := p_reviewed ->> 'detail';
  v_permit_no := p_reviewed ->> 'permit_no';
  v_authority := p_reviewed ->> 'authority';
  v_conditions := p_reviewed ->> 'conditions';

  if jsonb_typeof(p_reviewed -> 'items') is distinct from 'array'
     or exists (
       select 1 from jsonb_array_elements(p_reviewed -> 'items') item
       where jsonb_typeof(item) <> 'string' or btrim(item #>> '{}') = ''
     ) then
    raise exception 'items는 공백이 없는 문자열 배열이어야 합니다.';
  end if;
  select coalesce(array_agg(item.value order by item.ordinality), '{}'::text[])
  into v_items
  from jsonb_array_elements_text(p_reviewed -> 'items') with ordinality item(value, ordinality);

  if coalesce(jsonb_typeof(p_reviewed -> 'quantity'), 'null') not in ('null', 'number')
     or (
       jsonb_typeof(p_reviewed -> 'quantity') = 'number'
       and (
         (p_reviewed ->> 'quantity')::numeric <> trunc((p_reviewed ->> 'quantity')::numeric)
         or (p_reviewed ->> 'quantity')::numeric < -2147483648
         or (p_reviewed ->> 'quantity')::numeric > 2147483647
       )
     ) then
    raise exception 'quantity는 32비트 정수 또는 null이어야 합니다.';
  end if;
  v_quantity := (p_reviewed ->> 'quantity')::int;

  if coalesce(jsonb_typeof(p_reviewed -> 'issued_on'), 'null') not in ('null', 'string')
     or (
       jsonb_typeof(p_reviewed -> 'issued_on') = 'string'
       and (p_reviewed ->> 'issued_on') !~ '^\d{4}-\d{2}-\d{2}$'
     ) then
    raise exception 'issued_on은 YYYY-MM-DD 날짜 또는 null이어야 합니다.';
  end if;
  if jsonb_typeof(p_reviewed -> 'issued_on') = 'string' then
    begin
      v_issued_on := (p_reviewed ->> 'issued_on')::date;
    exception when datetime_field_overflow then
      raise exception 'issued_on은 실제 달력 날짜여야 합니다.';
    end;
  end if;

  if jsonb_typeof(p_reviewed -> 'status') is distinct from 'string'
     or (p_reviewed ->> 'status') not in (
       select unnest(enum_range(null::permit_status))::text
     ) then
    raise exception 'status가 유효하지 않습니다.';
  end if;
  v_status := (p_reviewed ->> 'status')::permit_status;

  if jsonb_typeof(p_reviewed -> 'evidence_storage_path') is distinct from 'string'
     or btrim(p_reviewed ->> 'evidence_storage_path') = '' then
    raise exception 'evidence_storage_path가 필요합니다.';
  end if;
  v_evidence_path := p_reviewed ->> 'evidence_storage_path';
  if not evidence_path_is_valid(v_evidence_path)
     or split_part(v_evidence_path, '/', 1)::uuid <> v_site_id
     or split_part(v_evidence_path, '/', 2) <> 'permit' then
    raise exception '확정 증빙 경로가 사업장 인허가 경로 규칙과 일치하지 않습니다.';
  end if;
  v_path_permit_id := split_part(split_part(v_evidence_path, '/', 3), '.', 1)::uuid;

  select * into v_existing
  from site_permits
  where site_id = v_site_id and permit_type = v_permit_type
  for update;

  if found and v_existing.id <> v_path_permit_id then
    raise exception '확정 증빙 경로가 기존 인허가 대상과 충돌합니다.';
  end if;
  if found and v_existing.issued_on is not null and v_issued_on is not null
     and v_issued_on < v_existing.issued_on then
    raise exception '기존 인허가보다 오래된 발급일로 확정할 수 없습니다.';
  end if;

  insert into site_permits (
    id, site_id, permit_type, applicable, grade, detail, items, quantity,
    permit_no, authority, issued_on, conditions, status, source, updated_by, updated_at
  ) values (
    v_path_permit_id, v_site_id, v_permit_type, v_applicable, v_grade, v_detail,
    v_items, v_quantity, v_permit_no, v_authority, v_issued_on, v_conditions,
    v_status, 'permit_document', v_actor, now()
  )
  on conflict (site_id, permit_type) do update set
    applicable = excluded.applicable,
    grade = excluded.grade,
    detail = excluded.detail,
    items = excluded.items,
    quantity = excluded.quantity,
    permit_no = excluded.permit_no,
    authority = excluded.authority,
    issued_on = excluded.issued_on,
    conditions = excluded.conditions,
    status = excluded.status,
    source = excluded.source,
    updated_by = excluded.updated_by,
    updated_at = excluded.updated_at
  returning id into v_permit_id;

  insert into attachments (
    id, site_id, entity_type, entity_id, storage_path, file_name, mime,
    size_bytes, uploaded_by
  ) values (
    v_document.id, v_site_id, 'permit', v_permit_id, v_evidence_path,
    v_document.original_filename, v_document.detected_mime,
    v_document.size_bytes, v_actor
  )
  on conflict (id) do nothing;

  select * into v_attachment from attachments where id = v_document.id;
  if v_attachment.site_id <> v_site_id
     or v_attachment.entity_type <> 'permit'
     or v_attachment.entity_id <> v_permit_id
     or v_attachment.storage_path <> v_evidence_path
     or v_attachment.file_name <> v_document.original_filename
     or v_attachment.mime is distinct from v_document.detected_mime
     or v_attachment.size_bytes is distinct from v_document.size_bytes then
    raise exception '문서 첨부 메타데이터가 기존 대상과 충돌합니다.';
  end if;

  update permit_documents
  set site_id_candidate = v_site_id,
      permit_type_candidate = v_permit_type,
      evidence_storage_path = v_evidence_path,
      status = 'confirmed',
      reviewer_id = v_actor,
      reviewed_at = now(),
      rejection_reason = null,
      updated_at = now()
  where id = v_document.id;

  return v_permit_id;
end
$$;

create or replace function reject_permit_document(
  p_document uuid,
  p_reason text
) returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := auth.uid();
  v_document permit_documents%rowtype;
begin
  if v_actor is null or not exists (
    select 1
    from profiles profile
    join role_assignments assignment on assignment.user_id = profile.id
    where profile.id = v_actor
      and profile.active
      and assignment.role = 'she_staff'
      and assignment.scope = 'company'
  ) then
    raise exception '활성 SHE팀 담당자만 인허가 문서를 반려할 수 있습니다.' using errcode = '42501';
  end if;
  if p_reason is null or btrim(p_reason) = '' then
    raise exception '반려 사유를 입력해야 합니다.';
  end if;

  select * into v_document
  from permit_documents
  where id = p_document
  for update;

  if not found then
    raise exception '검토할 인허가 문서를 찾을 수 없습니다.';
  end if;
  if v_document.status <> 'pending_review' then
    raise exception '대기 중인 인허가 문서만 반려할 수 있습니다.';
  end if;

  update permit_documents
  set status = 'rejected',
      reviewer_id = v_actor,
      reviewed_at = now(),
      rejection_reason = btrim(p_reason),
      updated_at = now()
  where id = v_document.id;
end
$$;

revoke all on function confirm_permit_document(uuid, jsonb) from public, anon;
grant execute on function confirm_permit_document(uuid, jsonb) to authenticated;
revoke all on function reject_permit_document(uuid, text) from public, anon;
grant execute on function reject_permit_document(uuid, text) to authenticated;
"""Verified local text-layer and OCR extraction for permit documents."""

import math
import re
import warnings
from collections.abc import Callable, Mapping
from contextlib import ExitStack
from dataclasses import dataclass
from io import BytesIO
from time import monotonic
from types import MappingProxyType
from typing import Final, TypeGuard

import pypdfium2
from PIL import Image, ImageOps, UnidentifiedImageError
from pypdf import PdfReader
from pypdf.errors import PdfReadError

from . import bounded_read
from .isolated_ocr import IsolatedOcrWorker
from .models import (
    DiscoveredDocument,
    DocumentExtractionError,
    ExtractedPage,
    ExtractionFailureKind,
    ExtractionMethod,
    PermitDocumentMime,
)
from .ocr import OcrEngine, TesseractOcr

_MEANINGFUL_TOKEN = re.compile(r"[0-9A-Za-z가-힣]{2,}")
_MIN_MEANINGFUL_CHARACTERS: Final = 8
_MIN_MEANINGFUL_TOKENS: Final = 2
_LONG_TEXT_CHARACTERS: Final = 12
_MAX_RENDER_SCALE: Final = 8.0
_MIN_DOCUMENT_SECONDS: Final = 1.0
_MAX_DOCUMENT_SECONDS: Final = 3_600.0


def _valid_positive_real(value: object, ceiling: float) -> bool:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    numeric_value = float(value)
    return math.isfinite(numeric_value) and 0 < numeric_value <= ceiling


@dataclass(frozen=True, slots=True)
class ExtractionLimits:
    """Resource ceilings for one untrusted local document."""

    max_source_bytes: int = 64 * 1024 * 1024
    max_image_dimension: int = 12_000
    max_image_pixels: int = 40_000_000
    max_pdf_pages: int = 200
    render_scale: float = 2.0
    max_rendered_dimension: int = 16_000
    max_rendered_pixels: int = 40_000_000
    max_total_rendered_pixels: int = 200_000_000
    max_document_seconds: float = 300.0

    def __post_init__(self) -> None:  # noqa: D105
        integer_limits = (
            self.max_source_bytes,
            self.max_image_dimension,
            self.max_image_pixels,
            self.max_pdf_pages,
            self.max_rendered_dimension,
            self.max_rendered_pixels,
            self.max_total_rendered_pixels,
        )
        if any(type(value) is not int or value <= 0 for value in integer_limits):
            raise DocumentExtractionError(
                ExtractionFailureKind.RESOURCE_LIMIT,
                "integer extraction limits must be positive integers",
            )
        if not _valid_positive_real(self.render_scale, _MAX_RENDER_SCALE):
            raise DocumentExtractionError(
                ExtractionFailureKind.RESOURCE_LIMIT,
                "render scale is outside the supported range",
            )
        if not _valid_positive_real(
            self.max_document_seconds,
            _MAX_DOCUMENT_SECONDS,
        ) or self.max_document_seconds < _MIN_DOCUMENT_SECONDS:
            raise DocumentExtractionError(
                ExtractionFailureKind.RESOURCE_LIMIT,
                "document OCR budget is outside the supported range",
            )


DEFAULT_EXTRACTION_LIMITS: Final = ExtractionLimits()


def _is_exact_tesseract(ocr: object) -> TypeGuard[TesseractOcr]:
    return type(ocr) is TesseractOcr


def _check_image_size(size: tuple[int, int], limits: ExtractionLimits) -> None:
    width, height = size
    if max(width, height) > limits.max_image_dimension or width * height > limits.max_image_pixels:
        raise DocumentExtractionError(
            ExtractionFailureKind.RESOURCE_LIMIT,
            "image dimensions exceed the extraction limit",
        )


def _ocr_page(
    image: Image.Image,
    page_number: int,
    ocr: OcrEngine,
    deadline: float,
) -> ExtractedPage:
    remaining = deadline - monotonic()
    if remaining <= 0:
        raise DocumentExtractionError(
            ExtractionFailureKind.OCR_TIMEOUT,
            "document OCR budget was exhausted",
        )
    result = ocr.extract(image, timeout_seconds=remaining)
    if monotonic() > deadline:
        raise DocumentExtractionError(
            ExtractionFailureKind.OCR_TIMEOUT,
            "document OCR budget was exhausted",
        )
    return ExtractedPage(
        page_number=page_number,
        text=result.text.strip(),
        method=ExtractionMethod.OCR,
        engine_version=result.engine_version,
    )


def _extract_image(
    contents: bytes,
    ocr: OcrEngine,
    limits: ExtractionLimits,
    deadline: float,
) -> tuple[ExtractedPage, ...]:
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", Image.DecompressionBombWarning)
            with ExitStack() as stack:
                source = stack.enter_context(Image.open(BytesIO(contents)))
                _check_image_size(source.size, limits)
                normalized = stack.enter_context(ImageOps.exif_transpose(source))
                _check_image_size(normalized.size, limits)
                image = stack.enter_context(normalized.convert("RGB"))
                return (_ocr_page(image, 1, ocr, deadline),)
    except (Image.DecompressionBombError, Image.DecompressionBombWarning) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.RESOURCE_LIMIT,
            "image decompression limit exceeded",
        ) from error
    except (OSError, UnidentifiedImageError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "image cannot be decoded",
        ) from error


def _text_pages(contents: bytes, max_pdf_pages: int) -> tuple[str, ...]:
    try:
        reader = PdfReader(BytesIO(contents), strict=True)
    except (PdfReadError, EOFError, UnicodeError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "PDF structure or text layer cannot be decoded",
        ) from error
    if reader.is_encrypted:
        raise DocumentExtractionError(
            ExtractionFailureKind.ENCRYPTED_PDF,
            "encrypted PDF requires manual review; no password was attempted",
        )
    if len(reader.pages) > max_pdf_pages:
        raise DocumentExtractionError(
            ExtractionFailureKind.RESOURCE_LIMIT,
            "PDF page count exceeds the extraction limit",
        )
    try:
        return tuple((page.extract_text() or "").strip() for page in reader.pages)
    except (PdfReadError, EOFError, UnicodeError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "PDF structure or text layer cannot be decoded",
        ) from error


def _usable_text(text: str) -> bool:
    normalized = " ".join(text.split())
    tokens = _MEANINGFUL_TOKEN.findall(normalized)
    meaningful_characters = sum(character.isalnum() for character in normalized)
    return meaningful_characters >= _MIN_MEANINGFUL_CHARACTERS and (
        len(tokens) >= _MIN_MEANINGFUL_TOKENS
        or meaningful_characters >= _LONG_TEXT_CHARACTERS
    )


def _extract_pdf(
    contents: bytes,
    ocr: OcrEngine,
    limits: ExtractionLimits,
    deadline: float,
) -> tuple[ExtractedPage, ...]:
    text_pages = _text_pages(contents, limits.max_pdf_pages)
    if all(_usable_text(text) for text in text_pages):
        return tuple(
            ExtractedPage(number, text, ExtractionMethod.TEXT_LAYER, None)
            for number, text in enumerate(text_pages, start=1)
        )
    try:
        rendered_document = pypdfium2.PdfDocument(contents)
        pages: list[ExtractedPage] = []
        total_rendered_pixels = 0
        try:
            for page_number, text in enumerate(text_pages, start=1):
                if _usable_text(text):
                    pages.append(
                        ExtractedPage(page_number, text, ExtractionMethod.TEXT_LAYER, None)
                    )
                    continue
                rendered_page = rendered_document[page_number - 1]
                try:
                    page_width, page_height = rendered_page.get_size()
                    rendered_width = math.ceil(page_width * limits.render_scale)
                    rendered_height = math.ceil(page_height * limits.render_scale)
                    rendered_pixels = rendered_width * rendered_height
                    total_rendered_pixels += rendered_pixels
                    if (
                        max(rendered_width, rendered_height) > limits.max_rendered_dimension
                        or rendered_pixels > limits.max_rendered_pixels
                        or total_rendered_pixels > limits.max_total_rendered_pixels
                    ):
                        raise DocumentExtractionError(
                            ExtractionFailureKind.RESOURCE_LIMIT,
                            "rendered PDF dimensions exceed the extraction limit",
                        )
                    bitmap = rendered_page.render(scale=limits.render_scale)
                    try:
                        if bitmap.width * bitmap.height > limits.max_rendered_pixels:
                            raise DocumentExtractionError(
                                ExtractionFailureKind.RESOURCE_LIMIT,
                                "rendered PDF bitmap exceeds the extraction limit",
                            )
                        image = bitmap.to_pil()
                        pages.append(_ocr_page(image, page_number, ocr, deadline))
                    finally:
                        bitmap.close()
                finally:
                    rendered_page.close()
        finally:
            rendered_document.close()
    except (pypdfium2.PdfiumError, IndexError, OSError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "PDF page cannot be rendered locally",
        ) from error
    return tuple(pages)


_EXTRACTORS: Final[
    Mapping[
        PermitDocumentMime,
        Callable[[bytes, OcrEngine, ExtractionLimits, float], tuple[ExtractedPage, ...]],
    ]
] = MappingProxyType(
    {
        PermitDocumentMime.PDF: _extract_pdf,
        PermitDocumentMime.JPEG: _extract_image,
        PermitDocumentMime.PNG: _extract_image,
    }
)


def extract_pages(
    document: DiscoveredDocument,
    ocr: OcrEngine,
    limits: ExtractionLimits = DEFAULT_EXTRACTION_LIMITS,
) -> tuple[ExtractedPage, ...]:
    """Extract 1-based page drafts without modifying or deleting the source."""
    deadline = monotonic() + limits.max_document_seconds
    contents = bounded_read.read_verified_contents(document, limits.max_source_bytes)
    extractor = _EXTRACTORS[document.mime_type]
    if _is_exact_tesseract(ocr):
        return extractor(contents, ocr, limits, deadline)
    with IsolatedOcrWorker(ocr) as isolated_ocr:
        return extractor(contents, isolated_ocr, limits, deadline)
"""Scan an inbox into reviewable permit-document successes and failures."""

import os
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path

from . import safe_io
from .models import (
    DiscoveredDocument,
    DiscoveryFailure,
    DiscoveryFailureKind,
    DocumentDiscoveryBatch,
    PermitDocumentDiscoveryError,
)


def _failure(kind: DiscoveryFailureKind, relative_path: Path | None, detail: str) -> DiscoveryFailure:
    """Build one explicit rejected-source record."""
    return DiscoveryFailure(kind, relative_path, detail)


def _relative(root: Path, path: Path) -> Path:
    """Return a normalized relative path for stable ordering and diagnostics."""
    return path.relative_to(root)


@dataclass(frozen=True, slots=True)
class _DirectoryToScan:
    """A verified directory that the scanner may visit without following a link."""

    path: Path


def _scan_directory(
    boundary: safe_io.RootBoundary, directory: Path
) -> Iterator[_DirectoryToScan | tuple[Path, Path] | DiscoveryFailure]:
    """Classify one directory's children without trusting link or reparse entries."""
    relative_directory = _relative(boundary.path, directory)
    directory_snapshot = safe_io.safe_path_snapshot(directory, boundary, relative_directory)
    match directory_snapshot:
        case DiscoveryFailure() as failure:
            yield failure
            return
        case safe_io.FileSnapshot() as snapshot:
            if not snapshot.is_directory:
                yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, "not a directory")
                return
    try:
        with os.scandir(directory) as entries:
            ordered_entries = tuple(sorted(entries, key=lambda entry: entry.name.casefold()))
    except OSError as error:
        yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, str(error))
        return
    for entry in ordered_entries:
