def _usable_text(text: str) -> bool:
    normalized = " ".join(text.split())
    tokens = _MEANINGFUL_TOKEN.findall(normalized)
    meaningful_characters = sum(character.isalnum() for character in normalized)
    return meaningful_characters >= _MIN_MEANINGFUL_CHARACTERS and (
        len(tokens) >= _MIN_MEANINGFUL_TOKENS
        or meaningful_characters >= _LONG_TEXT_CHARACTERS
    )


def _extract_pdf(
    contents: bytes,
    ocr: OcrEngine,
    limits: ExtractionLimits,
    deadline: float,
) -> tuple[ExtractedPage, ...]:
    text_pages = _text_pages(contents, limits.max_pdf_pages)
    if all(_usable_text(text) for text in text_pages):
        return tuple(
            ExtractedPage(number, text, ExtractionMethod.TEXT_LAYER, None)
            for number, text in enumerate(text_pages, start=1)
        )
    try:
        rendered_document = pypdfium2.PdfDocument(contents)
        pages: list[ExtractedPage] = []
        total_rendered_pixels = 0
        try:
            for page_number, text in enumerate(text_pages, start=1):
                if _usable_text(text):
                    pages.append(
                        ExtractedPage(page_number, text, ExtractionMethod.TEXT_LAYER, None)
                    )
                    continue
                rendered_page = rendered_document[page_number - 1]
                try:
                    page_width, page_height = rendered_page.get_size()
                    rendered_width = math.ceil(page_width * limits.render_scale)
                    rendered_height = math.ceil(page_height * limits.render_scale)
                    rendered_pixels = rendered_width * rendered_height
                    total_rendered_pixels += rendered_pixels
                    if (
                        max(rendered_width, rendered_height) > limits.max_rendered_dimension
                        or rendered_pixels > limits.max_rendered_pixels
                        or total_rendered_pixels > limits.max_total_rendered_pixels
                    ):
                        raise DocumentExtractionError(
                            ExtractionFailureKind.RESOURCE_LIMIT,
                            "rendered PDF dimensions exceed the extraction limit",
                        )
                    bitmap = rendered_page.render(scale=limits.render_scale)
                    try:
                        if bitmap.width * bitmap.height > limits.max_rendered_pixels:
                            raise DocumentExtractionError(
                                ExtractionFailureKind.RESOURCE_LIMIT,
                                "rendered PDF bitmap exceeds the extraction limit",
                            )
                        image = bitmap.to_pil()
                        pages.append(_ocr_page(image, page_number, ocr, deadline))
                    finally:
                        bitmap.close()
                finally:
                    rendered_page.close()
        finally:
            rendered_document.close()
    except (pypdfium2.PdfiumError, IndexError, OSError) as error:
        raise DocumentExtractionError(
            ExtractionFailureKind.CORRUPT_DOCUMENT,
            "PDF page cannot be rendered locally",
        ) from error
    return tuple(pages)


_EXTRACTORS: Final[
    Mapping[
        PermitDocumentMime,
        Callable[[bytes, OcrEngine, ExtractionLimits, float], tuple[ExtractedPage, ...]],
    ]
] = MappingProxyType(
    {
        PermitDocumentMime.PDF: _extract_pdf,
        PermitDocumentMime.JPEG: _extract_image,
        PermitDocumentMime.PNG: _extract_image,
    }
)


def extract_pages(
    document: DiscoveredDocument,
    ocr: OcrEngine,
    limits: ExtractionLimits = DEFAULT_EXTRACTION_LIMITS,
) -> tuple[ExtractedPage, ...]:
    """Extract 1-based page drafts without modifying or deleting the source."""
    deadline = monotonic() + limits.max_document_seconds
    contents = bounded_read.read_verified_contents(document, limits.max_source_bytes)
    extractor = _EXTRACTORS[document.mime_type]
    if _is_exact_tesseract(ocr):
        return extractor(contents, ocr, limits, deadline)
    with IsolatedOcrWorker(ocr) as isolated_ocr:
        return extractor(contents, isolated_ocr, limits, deadline)
"""Scan an inbox into reviewable permit-document successes and failures."""

import os
from collections.abc import Iterator
from dataclasses import dataclass
from pathlib import Path

from . import safe_io
from .models import (
    DiscoveredDocument,
    DiscoveryFailure,
    DiscoveryFailureKind,
    DocumentDiscoveryBatch,
    PermitDocumentDiscoveryError,
)


def _failure(kind: DiscoveryFailureKind, relative_path: Path | None, detail: str) -> DiscoveryFailure:
    """Build one explicit rejected-source record."""
    return DiscoveryFailure(kind, relative_path, detail)


def _relative(root: Path, path: Path) -> Path:
    """Return a normalized relative path for stable ordering and diagnostics."""
    return path.relative_to(root)


@dataclass(frozen=True, slots=True)
class _DirectoryToScan:
    """A verified directory that the scanner may visit without following a link."""

    path: Path


def _scan_directory(
    boundary: safe_io.RootBoundary, directory: Path
) -> Iterator[_DirectoryToScan | tuple[Path, Path] | DiscoveryFailure]:
    """Classify one directory's children without trusting link or reparse entries."""
    relative_directory = _relative(boundary.path, directory)
    directory_snapshot = safe_io.safe_path_snapshot(directory, boundary, relative_directory)
    match directory_snapshot:
        case DiscoveryFailure() as failure:
            yield failure
            return
        case safe_io.FileSnapshot() as snapshot:
            if not snapshot.is_directory:
                yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, "not a directory")
                return
    try:
        with os.scandir(directory) as entries:
            ordered_entries = tuple(sorted(entries, key=lambda entry: entry.name.casefold()))
    except OSError as error:
        yield _failure(DiscoveryFailureKind.INBOX_UNREADABLE, relative_directory, str(error))
        return
    for entry in ordered_entries:
        candidate = Path(entry.path)
        relative_path = _relative(boundary.path, candidate)
        try:
            snapshot = safe_io.path_snapshot(candidate)
        except OSError as error:
            yield _failure(DiscoveryFailureKind.FILE_UNREADABLE, relative_path, str(error))
            continue
        if snapshot.is_reparse:
            yield _failure(DiscoveryFailureKind.REPARSE_POINT, relative_path, "link or reparse point")
        elif snapshot.is_directory:
            yield _DirectoryToScan(candidate)
        elif snapshot.is_regular:
            yield candidate, relative_path


def _scan(boundary: safe_io.RootBoundary) -> Iterator[tuple[Path, Path] | DiscoveryFailure]:
    """Traverse every verified directory and yield candidates or independent failures."""
    pending = [boundary.path]
    while pending:
        directory = pending.pop()
        for result in _scan_directory(boundary, directory):
            match result:
                case DiscoveryFailure() as failure:
                    yield failure
                case _DirectoryToScan(path=path):
                    pending.append(path)
                case (path, relative_path):
                    yield path, relative_path


def _reparse_ancestor_failure(root: Path) -> DiscoveryFailure | None:
    """Report the first inbox ancestor that is a link or Windows reparse point."""
    for ancestor in safe_io.path_ancestors(root.parent, None):
        if safe_io.path_snapshot(ancestor).is_reparse:
            return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox ancestor is a link or reparse point")
    return None


def _inbox_initial_snapshot(inbox: Path, root: Path) -> safe_io.FileSnapshot | DiscoveryFailure:
    try:
        return safe_io.path_snapshot(root)
    except FileNotFoundError:
        return _failure(DiscoveryFailureKind.INBOX_MISSING, None, f"{inbox} does not exist")
    except OSError as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, None, str(error))


def _invalid_inbox_root(inbox: Path, initial: safe_io.FileSnapshot) -> DiscoveryFailure | None:
    if initial.is_reparse:
        return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox is a link or reparse point")
    if not initial.is_directory:
        return _failure(DiscoveryFailureKind.INBOX_NOT_DIRECTORY, None, f"{inbox} is not a directory")
    return None


def _inbox_root(inbox: Path) -> safe_io.RootBoundary | DiscoveryFailure:
    """Accept only an existing inbox with no link or reparse ancestor."""
    root = inbox.absolute()
    initial_result = _inbox_initial_snapshot(inbox, root)
    match initial_result:
        case DiscoveryFailure() as failure:
            return failure
        case safe_io.FileSnapshot() as initial:
            pass
    invalid_root = _invalid_inbox_root(inbox, initial)
    if invalid_root is not None:
        return invalid_root
    try:
        ancestor_failure = _reparse_ancestor_failure(root)
        if ancestor_failure is not None:
            return ancestor_failure
        resolved = root.resolve(strict=True)
    except (OSError, RuntimeError) as error:
        return _failure(DiscoveryFailureKind.INBOX_UNREADABLE, None, str(error))
    if not safe_io.same_lexical_path(root, resolved):
        return _failure(DiscoveryFailureKind.REPARSE_POINT, None, "inbox resolved through a different path")
    boundary = safe_io.RootBoundary(root, initial)
    root_failure = safe_io.verify_root(boundary, None)
    return root_failure if root_failure is not None else boundary


def discover_document_batch(inbox: Path) -> DocumentDiscoveryBatch:
    """Return every valid document and independent failure from one inbox traversal."""
    root_result = _inbox_root(inbox)
    match root_result:
        case DiscoveryFailure() as failure:
            return DocumentDiscoveryBatch((), (failure,))
        case safe_io.RootBoundary() as boundary:
            documents: list[DiscoveredDocument] = []
            failures: list[DiscoveryFailure] = []
            for discovered in _scan(boundary):
                match discovered:
                    case DiscoveryFailure() as failure:
                        failures.append(failure)
                    case (path, relative_path):
                        result = safe_io.read_document(path, boundary, relative_path)
                        match result:
                            case DiscoveryFailure() as failure:
                                failures.append(failure)
                            case DiscoveredDocument() as document:
                                documents.append(document)
            root_failure = safe_io.verify_root(boundary, None)
            if root_failure is not None:
                return DocumentDiscoveryBatch((), (*failures, root_failure))
            return DocumentDiscoveryBatch(tuple(sorted(documents, key=lambda document: document.relative_path.as_posix())), tuple(failures))


def discover_documents(inbox: Path) -> tuple[DiscoveredDocument, ...]:
    """Return usable documents while retaining root failures as typed exceptions."""
    batch = discover_document_batch(inbox)
    root_failures = tuple(failure for failure in batch.failures if failure.relative_path is None)
    if root_failures:
        raise PermitDocumentDiscoveryError(root_failures)
    return batch.documents
